    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const makeLine = (id: string, price: number): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: 1,
  });

  it("updates prices from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(2000)
        .mockResolvedValueOnce(3000),
    };
    const lines = [makeLine("a", 100), makeLine("b", 200)];
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(2000);
    expect(result[1]!.product.unitPriceCents).toBe(3000);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
  });

  it("preserves quantity and other product fields", async () => {
    const line: CartLine = {
      product: { id: "x", name: "Widget", unitPriceCents: 100, weightGrams: 500 },
      quantity: 3,
    };
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const [result] = await refreshPrices([line], fetcher);
    expect(result!.quantity).toBe(3);
    expect(result!.product.name).toBe("Widget");
    expect(result!.product.weightGrams).toBe(500);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices([makeLine("a", 100)], fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices([makeLine("a", 100)], fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices([makeLine("a", 100)], fetcher)).rejects.toThrow("fetch failed");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
