toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (id: string, weightGrams?: number, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a")], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns flat fee for non-empty cart below threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([line("a")], 3000)).toBe(500);
  });

  it("returns 0 when subtotal meets threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([line("a")], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([line("a")], 6000)).toBe(0);
  });

  it("returns flat fee when no threshold set", () => {
    const calc = new FlatShippingCalculator(799);
    expect(calc.computeShippingCents([line("a")], 100_000)).toBe(799);
  });

  it("returns 0 for empty cart even with flat fee", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("accepts 0 as valid flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([line("a")], 100)).toBe(0);
  });

  it("accepts 0 as valid freeOverCents (always free)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(calc.computeShippingCents([line("a")], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 500, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 500, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a")], 5000)).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 200g → first bracket
    expect(calc.computeShippingCents([line("a", 200)], 5000)).toBe(300);
    // 700g → second bracket
    expect(calc.computeShippingCents([line("a", 700)], 5000)).toBe(600);
    // 3000g → third bracket
    expect(calc.computeShippingCents([line("a", 3000)], 5000)).toBe(1200);
  });

  it("uses bracket boundary correctly (inclusive upper bound)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // exactly 500g → first bracket
    expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(300);
    // 501g → second bracket
    expect(calc.computeShippingCents([line("a", 501)], 5000)).toBe(600);
  });

  it("sorts brackets by weight regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([line("a", 400)], 5000)).toBe(300);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [{ upToGrams: 1000, costCents: 500 }],
      2000,
    );
    expect(calc.computeShippingCents([line("a", 2000)], 5000)).toBe(2000);
  });

  it("defaults overflow cost to heaviest bracket cost", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([line("a", 5000)], 5000)).toBe(600);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200g * 2 + 300g * 1 = 700g → second bracket
    const lines = [line("a", 200, 2), line("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 5000)).toBe(600);
  });
});

