+    expect(calc.computeShippingCents([line("a", 3000)], 5000)).toBe(1200);
+  });
+
+  it("uses bracket boundary correctly (inclusive upper bound)", () => {
+    const calc = new WeightBasedShippingCalculator([
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 600 },
+    ]);
+    // exactly 500g → first bracket
+    expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(300);
+    // 501g → second bracket
+    expect(calc.computeShippingCents([line("a", 501)], 5000)).toBe(600);
+  });
+
+  it("sorts brackets by weight regardless of input order", () => {
+    const calc = new WeightBasedShippingCalculator([
+      { upToGrams: 1000, costCents: 600 },
+      { upToGrams: 500, costCents: 300 },
+    ]);
+    expect(calc.computeShippingCents([line("a", 400)], 5000)).toBe(300);
+  });
+
+  it("uses overflow cost when weight exceeds all brackets", () => {
+    const calc = new WeightBasedShippingCalculator(
+      [{ upToGrams: 1000, costCents: 500 }],
+      2000,
+    );
+    expect(calc.computeShippingCents([line("a", 2000)], 5000)).toBe(2000);
+  });
+
+  it("defaults overflow cost to heaviest bracket cost", () => {
+    const calc = new WeightBasedShippingCalculator([
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 600 },
+    ]);
+    expect(calc.computeShippingCents([line("a", 5000)], 5000)).toBe(600);
+  });
+
+  it("sums weight across multiple lines", () => {
+    const calc = new WeightBasedShippingCalculator([
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 600 },
+    ]);
+    // 200g * 2 + 300g * 1 = 700g → second bracket
+    const lines = [line("a", 200, 2), line("b", 300, 1)];
+    expect(calc.computeShippingCents(lines, 5000)).toBe(600);
+  });
+});
